'use strict';

const http = require('http');

const FORCE_EXIT_MS = 3000;

const server = http.createServer((req, res) => {
  if (req.url === '/work') {
    setTimeout(() => {
      res.writeHead(200, { 'content-type': 'text/plain' });
      res.end('done');
    }, 500);
  } else {
    res.writeHead(404);
    res.end();
  }
});

// Listen on an ephemeral port and print it so the test harness can find it.
server.listen(0, '127.0.0.1', () => {
  const { port } = server.address();
  console.log(`PORT=${port}`);
});

let shuttingDown = false;

function forceExit() {
  console.error('force-exit deadline reached; destroying remaining connections');
  // Destroy any sockets still keeping the server open.
  for (const socket of Object.values(server._connections || {})) {
    socket.destroy();
  }
  process.exit(1);
}

process.on('SIGTERM', () => {
  if (shuttingDown) return;
  shuttingDown = true;

  // Backstop: if anything still holds us open after 3s, force exit non-zero.
  const timer = setTimeout(forceExit, FORCE_EXIT_MS);
  timer.unref();

  // Stop accepting new connections; existing connections are allowed to finish.
  server.close(() => {
    clearTimeout(timer);
    process.exit(0);
  });
});

