'use strict';

const { test } = require('node:test');
const assert = require('node:assert');
const { spawn } = require('node:child_process');
const path = require('node:path');
const net = require('node:net');

const SERVER_PATH = path.join(__dirname, 'graceful.js');
const FORCE_EXIT_MS = 3000;

function startServer() {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [SERVER_PATH], {
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    let stdout = '';
    let stderr = '';
    child.stdout.on('data', (d) => {
      stdout += d;
      const m = stdout.match(/PORT=(\d+)/);
      if (m) resolve({ child, port: Number(m[1]) });
    });
    child.stderr.on('data', (d) => (stderr += d));
    child.on('error', reject);
    child.on('exit', (code, signal) => {
      if (!stdout.includes('PORT=')) {
        reject(new Error(`server exited before printing port: code=${code} signal=${signal}\n${stderr}`));
      }
    });
  });
}

// Raw HTTP GET over a plain socket so we can control exactly when bytes are sent.
function request(port, path = '/work') {
  return new Promise((resolve, reject) => {
    const socket = net.connect(port, '127.0.0.1');
    let response = '';
    socket.setEncoding('utf8');
    socket.on('connect', () => {
      socket.write(`GET ${path} HTTP/1.1\r\nHost: 127.0.0.1:${port}\r\nConnection: close\r\n\r\n`);
    });
    socket.on('data', (d) => (response += d));
    socket.on('end', () => resolve(response));
    socket.on('error', reject);
  });
}

test('graceful shutdown: in-flight request completes, new connections refused, exits 0', async () => {
  const startedAt = Date.now();
  const { child, port } = await startServer();

  try {
    // Start an in-flight /work request.
    const inflightPromise = request(port, '/work');

    // Give the request time to connect and be received, then SIGTERM.
    await new Promise((r) => setTimeout(r, 100));
    child.kill('SIGTERM');

    // 1. The in-flight request must complete successfully.
    const response = await inflightPromise;
    assert.match(response, /^HTTP\/1\.1 200 OK/);
    assert.match(response, /done$/);

    // 2. A new request after SIGTERM must be refused (connection fails).
    await assert.rejects(
      () => request(port, '/work'),
      (err) => err.code === 'ECONNREFUSED' || err.code === 'ECONNRESET',
      'expected new connection after SIGTERM to be refused'
    );

    // 3. The process must exit 0, well before the force-exit deadline.
    const exitCode = await new Promise((resolve, reject) => {
      child.on('exit', (code, signal) => {
        if (code === 0) resolve(code);
        else reject(new Error(`expected exit code 0, got code=${code} signal=${signal}`));
      });
      child.on('error', reject);
    });

    const elapsed = Date.now() - startedAt;
    assert.strictEqual(exitCode, 0);
    assert.ok(
      elapsed < FORCE_EXIT_MS / 2,
      `process should exit well before the ${FORCE_EXIT_MS}ms deadline, took ${elapsed}ms`
    );
  } finally {
    // Safety: never leave a stray server running.
    if (child.exitCode === null && child.signalCode === null) {
      child.kill('SIGKILL');
    }
  }
});

